<?= view('partials/public_navbar', ['settings' => $settings ?? []]) ?>
<section class="hero"><div class="hero-inner"><div class="crumb"><a href="<?= site_url('/') ?>">Beranda</a> &nbsp;›&nbsp; Prestasi</div><div class="eyebrow">Bangga dengan pencapaian siswa</div><h1>Prestasi & Apresiasi</h1><p>Ruang untuk merayakan kerja keras, bakat, dan pencapaian siswa SMPIT Al Firdaus Purwodadi di bidang akademik maupun nonakademik.</p></div></section>
<main class="container">
<div class="section-head"><div><h2>Prestasi Siswa</h2><p>Setiap pencapaian adalah langkah untuk tumbuh, berani mencoba, dan menginspirasi.</p></div><span class="count"><?= count($achievements) ?> prestasi</span></div>
<div class="filters" role="search" aria-label="Filter prestasi"><input type="search" id="achievement-search" placeholder="Cari nama prestasi, siswa, atau lomba..." aria-label="Cari prestasi"><select id="achievement-level" aria-label="Filter tingkat prestasi"><option value="">Semua tingkat</option><?php $achievementLevels = array_values(array_unique(array_filter(array_map(static fn($item) => trim((string) ($item['level'] ?? '')), $achievements ?? [])))); sort($achievementLevels); foreach ($achievementLevels as $levelFilter): ?><option value="<?= esc(mb_strtolower($levelFilter), 'attr') ?>"><?= esc($levelFilter) ?></option><?php endforeach; ?></select></div>
<div class="grid" id="achievement-grid">
<?php if (!empty($achievements)): ?>
<?php foreach ($achievements as $achievement): ?>
<article class="card" data-level="<?= esc(mb_strtolower(trim((string) ($achievement['level'] ?? ''))), 'attr') ?>">
<div class="image-wrap">
<?php if (!empty($achievement['image'])): ?><img src="<?= base_url('assets/images/achievements/' . rawurlencode($achievement['image'])) ?>" alt="<?= esc($achievement['title']) ?>" loading="lazy"><?php else: ?><div class="image-placeholder" aria-hidden="true">🏆</div><?php endif; ?>
<?php if (!empty($achievement['level'])): ?><span class="level"><?= esc($achievement['level']) ?></span><?php endif; ?>
</div>
<div class="body">
<div class="date"><?= !empty($achievement['achievement_date']) ? esc(date('d M Y', strtotime($achievement['achievement_date']))) : 'Prestasi sekolah' ?></div>
<h3><?= esc($achievement['title']) ?></h3>
<?php if (!empty($achievement['student_name'])): ?><div class="student">✦ <?= esc($achievement['student_name']) ?></div><?php endif; ?>
<?php if (!empty($achievement['competition'])): ?><p class="desc"><strong><?= esc($achievement['competition']) ?></strong></p><?php endif; ?>
<?php if (!empty($achievement['description'])): ?><p class="desc"><?= esc($achievement['description']) ?></p><?php endif; ?>
</div>
</article>
<?php endforeach; ?>
<?php else: ?>
<div class="empty"><strong>Prestasi segera hadir</strong><p>Data prestasi siswa belum tersedia. Silakan tambahkan prestasi melalui panel admin setelah fitur pengelolaan prestasi diaktifkan.</p></div>
<?php endif; ?>
</div>
</main>
<script>(function(){const s=document.getElementById('achievement-search'),l=document.getElementById('achievement-level'),cards=[...document.querySelectorAll('#achievement-grid .card')],grid=document.getElementById('achievement-grid');const empty=document.createElement('div');empty.className='filter-empty';empty.textContent='Tidak ada prestasi yang cocok dengan pencarian atau filter ini.';grid.appendChild(empty);function apply(){const q=s.value.trim().toLocaleLowerCase('id'),level=l.value;let n=0;cards.forEach(c=>{const show=c.textContent.toLocaleLowerCase('id').includes(q)&&(!level||c.dataset.level===level);c.style.display=show?'':'none';if(show)n++});empty.style.display=cards.length&&n===0?'block':'none'}s.addEventListener('input',apply);l.addEventListener('change',apply)})();</script>
